    def box_manifest_instance_exists(
        self,
        driver,
        imported,
        box: str,
        manifest_id: str,
        type_label: str,
        world_id: str = "",
    ) -> bool:
        _TypeDB, _Credentials, _DriverOptions, _DriverTlsConfig, TransactionType = imported[0]
        clean_world_id = str(world_id or "").strip()
