    def box_manifest_delete_batch_query(
        self,
        box: str,
        manifest_id: str,
        type_label: str,
        batch_size: int,
        world_id: str = "",
    ) -> str:
        variable = "$r" if str(type_label) == "ontology-assertion" else "$n"
        clean_world_id = str(world_id or "").strip()
        return (
            "match " + variable + " isa " + str(type_label)
            + ", has ontology-box " + typedb_string(box)
            + ", has ontology-manifest-id " + typedb_string(manifest_id)
            + (", has ontology-world-id " + typedb_string(clean_world_id) if clean_world_id else "")
            + "; limit " + str(max(1, int(batch_size or 1))) + "; delete " + variable + ";"
        )

    def delete_box_manifest_rows_in_batches(
        self,
        driver,
        imported,
        box: str,
        manifest_id: str,
        batch_size: int = None,
        max_batches: int = None,
        world_id: str = "",
    ) -> Dict[str, object]:
        """Clear a retry candidate by its exact Manifest provenance.

        Scoped generations can be shared by retained Manifests, so a realtime
        retry must not enumerate or delete every generation that happens to
        have the same scope fingerprint. ``ontology-manifest-id`` identifies
        only the incomplete candidate being retried, including its marker.
        """
        clean_box = str(box or "").strip()
        clean_manifest_id = str(manifest_id or "").strip()
        clean_world_id = str(world_id or "").strip()
        if not clean_box or not clean_manifest_id:
            return {"status": "skipped", "deletedBatchCount": 0}
        _TypeDB, _Credentials, _DriverOptions, _DriverTlsConfig, TransactionType = imported[0]
        configured_batch_size = self.abox_delete_batch_size() if batch_size is None else int(batch_size or 0)
        safe_batch_size = max(1, min(5000, configured_batch_size))
        safe_max_batches = None if max_batches is None else max(0, int(max_batches or 0))
        deleted_batches = 0
        remaining_types: List[str] = []
        for type_label in ["ontology-assertion", "ontology-node"]:
            while self.box_manifest_instance_exists(
                driver,
                imported,
                clean_box,
                clean_manifest_id,
                type_label,
                world_id=clean_world_id,
            ):
                if safe_max_batches is not None and deleted_batches >= safe_max_batches:
                    remaining_types.append(type_label)
                    break
                query = self.box_manifest_delete_batch_query(
                    clean_box,
                    clean_manifest_id,
                    type_label,
                    safe_batch_size,
                    world_id=clean_world_id,
                )

                def delete_batch():
                    with typedb_operation_timeout(self.write_operation_timeout_seconds(), "TypeDB ABox manifest candidate delete batch"):
                        with driver.transaction(
                            self.database,
                            TransactionType.WRITE,
                            options=self.write_transaction_options(),
                        ) as tx:
                            tx.query(query).resolve()
                            tx.commit()

                self.with_typedb_retries(delete_batch)
                deleted_batches += 1
            if remaining_types:
                break
        if safe_max_batches is not None and deleted_batches >= safe_max_batches:
            for type_label in ["ontology-assertion", "ontology-node"]:
                if self.box_manifest_instance_exists(
                    driver,
                    imported,
                    clean_box,
                    clean_manifest_id,
                    type_label,
                    world_id=clean_world_id,
                ) and type_label not in remaining_types:
                    remaining_types.append(type_label)
        return {
            "status": "partial" if remaining_types else "ok",
            "ontologyBox": clean_box,
            "worldviewManifestId": clean_manifest_id,
            "worldId": clean_world_id,
            "batchSize": safe_batch_size,
            "maxBatches": safe_max_batches,
            "deletedBatchCount": deleted_batches,
            "remainingRowTypes": remaining_types,
        }

    def box_snapshot_delete_batch_query(
        self,
        box: str,
        snapshot_id: str,
        type_label: str,
        batch_size: int,
    ) -> str:
        variable = "$r" if str(type_label) == "ontology-assertion" else "$n"
        return (
            "match " + variable + " isa " + str(type_label)
            + ", has ontology-box " + typedb_string(box)
            + ", has ontology-snapshot-id " + typedb_string(snapshot_id)
            + "; limit " + str(max(1, int(batch_size or 1))) + "; delete " + variable + ";"
        )

    def delete_box_snapshot_rows_in_batches(
        self,
        driver,
        imported,
        box: str,
        snapshot_id: str,
        batch_size: int = None,
        max_batches: int = None,
        deadline_monotonic: float = None,
    ) -> Dict[str, object]:
        """Delete one inactive ABox generation in short TypeDB writes.

        ``max_batches`` turns the operation into a bounded maintenance slice.
        The active projection path uses that mode so historical cleanup cannot
        consume an entire realtime reasoning cycle.
        """
        clean_box = str(box or "").strip()
        clean_snapshot_id = str(snapshot_id or "").strip()
        if not clean_box or not clean_snapshot_id:
            return {"status": "skipped", "deletedBatchCount": 0}
        _TypeDB, _Credentials, _DriverOptions, _DriverTlsConfig, TransactionType = imported[0]
        configured_batch_size = self.abox_delete_batch_size() if batch_size is None else int(batch_size or 0)
        safe_batch_size = max(1, min(5000, configured_batch_size))
        safe_max_batches = None if max_batches is None else max(0, int(max_batches or 0))
        started_at = time.monotonic()
        deleted_batches = 0
        remaining_types: List[str] = []
        time_budget_exhausted = False
        for type_label in ["ontology-assertion", "ontology-node"]:
            while True:
                if deadline_monotonic is not None and time.monotonic() >= deadline_monotonic:
                    time_budget_exhausted = True
                    remaining_types.append(type_label)
                    break
                if not self.box_snapshot_instance_exists(
                    driver,
                    imported,
                    clean_box,
                    clean_snapshot_id,
                    type_label,
                ):
                    break
                if safe_max_batches is not None and deleted_batches >= safe_max_batches:
                    remaining_types.append(type_label)
                    break
                query = self.box_snapshot_delete_batch_query(
                    clean_box,
                    clean_snapshot_id,
                    type_label,
                    safe_batch_size,
                )

                def delete_batch():
                    with typedb_operation_timeout(self.write_operation_timeout_seconds(), "TypeDB ABox candidate delete batch"):
                        with driver.transaction(
                            self.database,
                            TransactionType.WRITE,
                            options=self.write_transaction_options(),
                        ) as tx:
                            tx.query(query).resolve()
                            tx.commit()

                self.with_typedb_retries(delete_batch)
                deleted_batches += 1
            if remaining_types:
                break
        if (
            not time_budget_exhausted
            and safe_max_batches is not None
            and deleted_batches >= safe_max_batches
        ):
            for type_label in ["ontology-assertion", "ontology-node"]:
                if self.box_snapshot_instance_exists(
                    driver,
                    imported,
                    clean_box,
                    clean_snapshot_id,
                    type_label,
                ) and type_label not in remaining_types:
                    remaining_types.append(type_label)
        return {
            "status": "partial" if remaining_types else "ok",
            "ontologyBox": clean_box,
            "aboxSnapshotId": clean_snapshot_id,
            "batchSize": safe_batch_size,
            "maxBatches": safe_max_batches,
            "deletedBatchCount": deleted_batches,
            "remainingRowTypes": remaining_types,
            "timeBudgetExhausted": time_budget_exhausted,
            "resumeRequired": bool(remaining_types),
            "durationMs": int((time.monotonic() - started_at) * 1000),
        }

    def discard_abox_generation(self, snapshot_id: str) -> Dict[str, object]:
        """Delete one failed, inactive candidate generation immediately."""
        clean_snapshot_id = str(snapshot_id or "").strip()
        if not clean_snapshot_id:
            return {
                "configured": bool(self.address),
                "status": "skipped",
                "graphStore": "typedb",
                "aboxSnapshotId": "",
                "reason": "ABox snapshot id is empty.",
            }
        if self.scoped_manifest_metadata(clean_snapshot_id):
            return self.discard_scoped_abox_manifest(clean_snapshot_id)
        active = self.active_abox_metadata()
        if str(active.get("aboxSnapshotId") or "").strip() == clean_snapshot_id:
            return {
                "configured": True,
                "status": "protected-active",
                "graphStore": "typedb",
                "aboxSnapshotId": clean_snapshot_id,
                "reason": "The active ABox generation cannot be discarded.",
            }
        imported = self.driver_imports()
        if imported[0] is None:
            return {
                "configured": True,
                "status": "driver-missing",
                "graphStore": "typedb",
                "aboxSnapshotId": clean_snapshot_id,
                "reason": str(imported[1])[:180],
            }
        try:
            def operation():
                driver = self.open_driver(imported)
                try:
                    self.ensure_database(driver)
                    return self.delete_box_snapshot_rows_in_batches(
                        driver,
                        imported,
                        "ABox",
                        clean_snapshot_id,
                    )
                finally:
                    self.close_driver(driver)

            result = self.with_typedb_retries(operation)
            return {
                "configured": True,
                "graphStore": "typedb",
                **dict(result or {}),
            }
        except Exception as error:  # noqa: BLE001 - cleanup state remains visible to the circuit breaker.
            return {
                "configured": True,
                "status": "error",
                "graphStore": "typedb",
                "aboxSnapshotId": clean_snapshot_id,
                "reasonCode": typedb_error_code(error),
                "reason": str(error)[:220],
            }

    def delete_box_rows_in_batches(self, driver, imported, boxes: Iterable[str]) -> Dict[str, object]:
        _TypeDB, _Credentials, _DriverOptions, _DriverTlsConfig, TransactionType = imported[0]
        batch_size = self.abox_delete_batch_size()
        deleted_batches = 0
        for box in sorted({str(item or "").strip() for item in boxes or [] if str(item or "").strip()}):
            for type_label in ["ontology-assertion", "ontology-node"]:
                while self.box_instance_exists(driver, imported, box, type_label):
                    query = self.box_delete_batch_query(box, type_label, batch_size)

                    def delete_batch():
                        with typedb_operation_timeout(self.write_operation_timeout_seconds(), "TypeDB ABox delete batch"):
                            with driver.transaction(
                                self.database,
                                TransactionType.WRITE,
                                options=self.write_transaction_options(),
                            ) as tx:
                                tx.query(query).resolve()
                                tx.commit()

                    self.with_typedb_retries(delete_batch)
                    deleted_batches += 1
        return {
            "status": "ok",
            "boxes": sorted({str(item or "").strip() for item in boxes or [] if str(item or "").strip()}),
            "batchSize": batch_size,
            "deletedBatchCount": deleted_batches,
        }

    def delete_world_abox_control_rows(self, driver, imported, world_id: str = "") -> Dict[str, object]:
        """Replace only one world's pointer and activation journal.

        Historical code replaced every ``ABoxControl`` record during one
        account's activation.  World-aware controls are intentionally
        independent, so the delete predicate includes the durable world
        attribute whenever the caller has an explicit world id.
        """
        _TypeDB, _Credentials, _DriverOptions, _DriverTlsConfig, TransactionType = imported[0]
        query = (
            'match $n isa ontology-node, has ontology-box "ABoxControl"'
            + (", has ontology-world-id " + typedb_string(world_id) if str(world_id or "").strip() else "")
            + "; delete $n;"
        )

        def operation():
            with typedb_operation_timeout(self.write_operation_timeout_seconds(), "TypeDB world ABox control swap"):
                with driver.transaction(
                    self.database,
                    TransactionType.WRITE,
                    options=self.write_transaction_options(),
                ) as tx:
                    tx.query(query).resolve()
                    tx.commit()

        self.with_typedb_retries(operation)
        return {"status": "ok", "worldId": str(world_id or "")}

    @staticmethod
    def scoped_abox_control_delete_query(
        kind: str,
        world_id: str = "",
        scope_id: str = "",
    ) -> str:
        """Delete one control-plane node class, optionally for one scope."""
        return (
            'match $n isa ontology-node, has ontology-box "ABoxControl", has ontology-kind '
            + typedb_string(kind)
            + (
                ", has ontology-world-id " + typedb_string(world_id)
                if str(world_id or "").strip()
                else ""
            )
            + (
                ", has ontology-scope-id " + typedb_string(scope_id)
                if str(scope_id or "").strip()
                else ""
            )
            + "; delete $n;"
        )

    def replace_scoped_abox_control_graph(
        self,
        driver,
        imported,
        graph: PortfolioOntology,
        world_id: str = "",
        scope_ids: Iterable[str] = None,
        replace_all_scope_pointers: bool = False,
    ) -> Dict[str, object]:
        """Atomically swap the active Manifest and only changed scope controls.

        Scope pointers deliberately outlive individual Manifest ids. The active
        Manifest row and activation journal are always replaced, while stable
        scope pointers remain untouched. This turns the normal live path into
        a small control-plane patch rather than a rewrite of every holding.
        """
        _TypeDB, _Credentials, _DriverOptions, _DriverTlsConfig, TransactionType = imported[0]
        clean_scope_ids = sorted({
            str(scope_id or "").strip()
            for scope_id in scope_ids or []
            if str(scope_id or "").strip()
        })
        delete_queries = [
            self.scoped_abox_control_delete_query("worldview-manifest-active-pointer", world_id),
            self.scoped_abox_control_delete_query("abox-activation-pending", world_id),
        ]
        if replace_all_scope_pointers:
            delete_queries.append(
                self.scoped_abox_control_delete_query("abox-scope-active-pointer", world_id)
            )
        else:
            delete_queries.extend(
                self.scoped_abox_control_delete_query(
                    "abox-scope-active-pointer",
                    world_id,
                    scope_id,
                )
                for scope_id in clean_scope_ids
            )
        insert_queries = self.graph_insert_queries(graph)
        queries = delete_queries + insert_queries
        if not queries:
            return {
                "status": "skipped",
                "worldId": str(world_id or ""),
                "queryCount": 0,
                "transactionCount": 0,
            }
        # Control rows are tiny and must change together. Keep a bounded but
        # substantially larger transaction than the ABox row writer, whose
        # one-edge batches protect a very different high-volume path.
        raw_limit = number_or_none(runtime_settings().get("typedbScopedControlWriteTransactionQueryCount"))
        transaction_limit = int(raw_limit) if raw_limit is not None else 256
        transaction_limit = max(8, min(512, transaction_limit))
        transaction_count = 0
        for offset in range(0, len(queries), transaction_limit):
            query_batch = queries[offset: offset + transaction_limit]

            def write_batch():
                with typedb_operation_timeout(
                    self.write_operation_timeout_seconds(),
                    "TypeDB scoped ABox control patch",
                ):
                    with driver.transaction(
                        self.database,
                        TransactionType.WRITE,
                        options=self.write_transaction_options(),
                    ) as tx:
                        for query in query_batch:
                            tx.query(query).resolve()
                        tx.commit()

            self.with_typedb_retries(write_batch)
            transaction_count += 1
        return {
            "status": "ok",
            "worldId": str(world_id or ""),
            "mode": (
                "full-scoped-control-rebuild"
                if replace_all_scope_pointers
                else "incremental-scoped-control-patch"
            ),
            "replacedScopeIds": clean_scope_ids,
            "scopePointerWriteCount": len([
                entity
                for entity in graph.entities
                if str(entity.kind or "") == "abox-scope-active-pointer"
            ]),
            "queryCount": len(queries),
            "transactionCount": transaction_count,
            "atomic": transaction_count == 1,
        }

    def clear_scoped_abox_pending_activation(self, world_id: str = "") -> Dict[str, object]:
        """Clear only the activation journal after aligned native inference."""
        imported = self.driver_imports()
        if imported[0] is None:
            return self.driver_missing_result(imported[1], PortfolioOntology("typedb-scoped-control"))
        _TypeDB, _Credentials, _DriverOptions, _DriverTlsConfig, TransactionType = imported[0]
        query = self.scoped_abox_control_delete_query("abox-activation-pending", world_id)
        try:
            def operation():
                driver = self.open_driver(imported)
                try:
                    self.ensure_database(driver)
                    self.ensure_schema(driver, imported)
                    with typedb_operation_timeout(
                        self.write_operation_timeout_seconds(),
                        "TypeDB scoped ABox activation journal clear",
                    ):
                        with driver.transaction(
                            self.database,
                            TransactionType.WRITE,
                            options=self.write_transaction_options(),
                        ) as tx:
                            tx.query(query).resolve()
                            tx.commit()
                finally:
                    self.close_driver(driver)

            self.with_typedb_retries(operation)
            return {
                "configured": True,
                "status": "ok",
                "graphStore": "typedb",
                "worldId": str(world_id or ""),
                "mode": "pending-journal-clear",
            }
        except Exception as error:  # noqa: BLE001 - retain the journal when its clear cannot commit.
            return {
                "configured": True,
                "status": "error",
                "graphStore": "typedb",
                "worldId": str(world_id or ""),
                "reasonCode": typedb_error_code(error),
                "reason": str(error)[:220],
            }

    def abox_candidate_snapshot_ids(self) -> List[str]:
        rows = self.read_rows(
            'match $n isa ontology-node, has ontology-box "ABox", has ontology-snapshot-id $snapshotId;',
            ["snapshotId"],
            label="typedb.abox-candidate-cleanup-audit",
        )
        return sorted({str(row.get("snapshotId") or "").strip() for row in rows if str(row.get("snapshotId") or "").strip()})

    def cleanup_inactive_abox_candidates(
        self,
        driver,
        imported,
        active_snapshot_id: str = "",
    ) -> Dict[str, object]:
        """Remove incomplete candidate generations without touching the active ABox.

        Candidate writes are committed in bounded batches. If a process exits
        between node and relation batches, those partial generations must not
        accumulate indefinitely or create ambiguous endpoint matches for the
        next candidate. The active pointer is the only generation preserved.
        """
        active = str(active_snapshot_id or "").strip()
        candidates = self.abox_candidate_snapshot_ids()
        stale_candidates = [snapshot_id for snapshot_id in candidates if snapshot_id != active]
        deleted_batches = 0
        if active:
            for snapshot_id in stale_candidates:
                result = self.delete_box_snapshot_rows_in_batches(
                    driver,
                    imported,
                    "ABox",
                    snapshot_id,
                )
                deleted_batches += int(number_or_none(result.get("deletedBatchCount")) or 0)
        elif candidates:
            result = self.delete_box_rows_in_batches(driver, imported, ["ABox"])
            deleted_batches += int(number_or_none(result.get("deletedBatchCount")) or 0)

        # ABoxStaging belongs to the previous two-box rollout. It is never an
        # active generation in the pointer model and can be cleaned safely.
        legacy = self.delete_box_rows_in_batches(driver, imported, ["ABoxStaging"])
        deleted_batches += int(number_or_none(legacy.get("deletedBatchCount")) or 0)
        return {
            "status": "ok",
            "activeAboxSnapshotId": active,
            "candidateSnapshotIds": candidates,
            "removedCandidateSnapshotIds": stale_candidates,
            "deletedBatchCount": deleted_batches,
            "legacyStagingCleanup": legacy,
        }

    def drain_inactive_abox_generations_incrementally(
        self,
        driver,
        imported,
        active_snapshot_id: str = "",
        excluded_snapshot_ids: Iterable[str] = None,
    ) -> Dict[str, object]:
        """Reclaim a bounded slice of inactive ABox generations.

        Native inference and notification delivery must not wait for a full
        historical deletion. The active pointer is already verified before
        this method runs, and pending hand-offs are never cleaned here.
        """
        active = str(active_snapshot_id or "").strip()
        excluded = {
            str(item or "").strip()
            for item in excluded_snapshot_ids or []
            if str(item or "").strip()
        }
        if not active:
            return {
                "status": "skipped",
                "reason": "No active ABox generation is available for safe incremental cleanup.",
                "activeAboxSnapshotId": active,
                "deletedBatchCount": 0,
            }
        pending = self.pending_abox_activation()
        if str(pending.get("status") or "") == "pending":
            return {
                "status": "skipped",
                "reason": "ABox activation is pending native inference.",
                "activeAboxSnapshotId": active,
                "pendingAboxSnapshotId": str(pending.get("candidateAboxSnapshotId") or ""),
                "deletedBatchCount": 0,
            }
        max_batches = self.abox_incremental_cleanup_max_batches_per_save()
        if max_batches <= 0:
            return {
                "status": "skipped",
                "reason": "Incremental ABox cleanup is disabled by runtime setting.",
                "activeAboxSnapshotId": active,
                "deletedBatchCount": 0,
            }
        candidates = [
            snapshot_id
            for snapshot_id in self.abox_candidate_snapshot_ids()
            if snapshot_id != active and snapshot_id not in excluded
        ]
        markers = self.abox_projection_marker_rows()
        marker_by_snapshot: Dict[str, Dict[str, object]] = {}
        for marker in markers:
            snapshot_id = str(marker.get("aboxSnapshotId") or marker.get("snapshotId") or "").strip()
            if snapshot_id and snapshot_id in candidates:
                previous = marker_by_snapshot.get(snapshot_id)
                if previous is None or (
                    str(marker.get("updatedAt") or ""), str(marker.get("id") or "")
                ) > (
                    str(previous.get("updatedAt") or ""), str(previous.get("id") or "")
                ):
                    marker_by_snapshot[snapshot_id] = marker
        incomplete = sorted(snapshot_id for snapshot_id in candidates if snapshot_id not in marker_by_snapshot)
        completed_newest_first = sorted(
            marker_by_snapshot,
            key=lambda snapshot_id: (
                str(marker_by_snapshot[snapshot_id].get("updatedAt") or ""),
                str(marker_by_snapshot[snapshot_id].get("id") or ""),
                snapshot_id,
            ),
            reverse=True,
        )
        keep_count = self.abox_inactive_generation_keep_count()
        retained = completed_newest_first[:keep_count]
        completed_oldest_first = list(reversed(completed_newest_first[keep_count:]))
        targets = incomplete + completed_oldest_first
        deleted_batches = 0
        attempted: List[str] = []
        slices: List[Dict[str, object]] = []
        remaining_budget = max_batches
        for snapshot_id in targets:
            if remaining_budget <= 0:
                break
            cleanup = self.delete_box_snapshot_rows_in_batches(
                driver,
                imported,
                "ABox",
                snapshot_id,
                batch_size=self.abox_incremental_cleanup_batch_size(),
                max_batches=remaining_budget,
            )
            attempted.append(snapshot_id)
            slices.append(cleanup)
            deleted = int(number_or_none(cleanup.get("deletedBatchCount")) or 0)
            deleted_batches += deleted
            remaining_budget = max(0, remaining_budget - deleted)
            if str(cleanup.get("status") or "") == "partial":
                break
        remaining = [snapshot_id for snapshot_id in targets if snapshot_id not in attempted]
        if slices and str(slices[-1].get("status") or "") == "partial":
            remaining = [str(slices[-1].get("aboxSnapshotId") or "")] + remaining
        return {
            "status": "partial" if remaining else "ok",
            "activeAboxSnapshotId": active,
            "excludedSnapshotIds": sorted(excluded),
            "candidateSnapshotIds": candidates,
            "retainedInactiveSnapshotIds": retained,
            "cleanupTargetSnapshotIds": targets,
            "attemptedSnapshotIds": attempted,
            "remainingSnapshotIds": [item for item in remaining if item],
            "batchSize": self.abox_incremental_cleanup_batch_size(),
            "maxBatches": max_batches,
            "deletedBatchCount": deleted_batches,
            "slices": slices,
        }

    def prune_inactive_abox_generations(
        self,
        driver,
        imported,
        active_snapshot_id: str = "",
        keep_inactive_count: int = None,
        max_generations: int = None,
    ) -> Dict[str, object]:
        """Bound retention to completed ABox generations after activation.

        This intentionally operates on completion markers, not every physical
        ABox row. A marker is written only after the candidate rows are present
        and verified; preserving the active pointer plus recent marked
        generations makes deletion safe in the single-writer activation path.
        Unmarked interrupted candidates remain available for retry diagnostics
        and are cleared only when that exact snapshot is retried.
        """
        active = str(active_snapshot_id or "").strip()
        active_metadata: Dict[str, object] = {}
        if active.startswith("abox-manifest:") or not active:
            try:
                active_metadata = self.active_abox_metadata()
            except Exception:
                active_metadata = {}
        if str(active_metadata.get("scopedAboxManifestVersion") or "") == SCOPED_ABOX_MANIFEST_VERSION:
            return self.prune_inactive_scoped_abox_manifests_in_driver(
                driver,
                imported,
                active_manifest_id=active or str(
                    active_metadata.get("worldviewManifestId") or active_metadata.get("aboxSnapshotId") or ""
                ),
                keep_inactive_count=keep_inactive_count,
                max_manifests=max_generations,
            )
        keep_count = (
            self.abox_inactive_generation_keep_count()
            if keep_inactive_count is None
            else max(0, min(5, int(keep_inactive_count or 0)))
        )
        max_count = (
            self.abox_inactive_generation_max_prune_per_save()
            if max_generations is None
            else max(0, min(10, int(max_generations or 0)))
        )
        markers = self.abox_projection_marker_rows()
        marker_by_snapshot: Dict[str, Dict[str, object]] = {}
        for marker in markers:
            snapshot_id = str(marker.get("aboxSnapshotId") or marker.get("snapshotId") or "").strip()
            if not snapshot_id or snapshot_id == active:
                continue
            previous = marker_by_snapshot.get(snapshot_id)
            if previous is None or (
                str(marker.get("updatedAt") or ""), str(marker.get("id") or "")
            ) > (
                str(previous.get("updatedAt") or ""), str(previous.get("id") or "")
            ):
                marker_by_snapshot[snapshot_id] = marker
        ordered_inactive = sorted(
            marker_by_snapshot,
            key=lambda snapshot_id: (
                str(marker_by_snapshot[snapshot_id].get("updatedAt") or ""),
                str(marker_by_snapshot[snapshot_id].get("id") or ""),
                snapshot_id,
            ),
            reverse=True,
        )
        retained = ordered_inactive[:keep_count]
        # Preserve the most recent completed predecessor, then drain the
        # oldest backlog first. This keeps a useful rollback/audit generation
        # while reducing the worst historical amplification immediately.
        removable = list(reversed(ordered_inactive[keep_count:]))[:max_count]
        deleted_batches = 0
        removed = []
        for snapshot_id in removable:
            result = self.delete_box_snapshot_rows_in_batches(driver, imported, "ABox", snapshot_id)
            deleted_batches += int(number_or_none(result.get("deletedBatchCount")) or 0)
            removed.append(snapshot_id)
        return {
            "status": "ok",
            "activeAboxSnapshotId": active,
            "keepInactiveGenerationCount": keep_count,
            "maxGenerationsPerSave": max_count,
            "completedInactiveCandidateCount": len(ordered_inactive),
            "retainedInactiveSnapshotIds": retained,
            "removedCandidateSnapshotIds": removed,
            "remainingInactiveCandidateCount": max(0, len(ordered_inactive) - len(removed)),
            "deletedBatchCount": deleted_batches,
        }

    def clear_boxes_in_batches(self, boxes: Iterable[str]) -> Dict[str, object]:
        clean_boxes = sorted({str(item or "").strip() for item in boxes or [] if str(item or "").strip()})
        if not clean_boxes:
            return {"status": "skipped", "boxes": [], "deletedBatchCount": 0}
        imported = self.driver_imports()
        if imported[0] is None:
            return {"status": "driver-missing", "boxes": clean_boxes, "reason": str(imported[1])[:180]}
        try:
            def operation():
                driver = self.open_driver(imported)
                try:
                    self.ensure_database(driver)
                    self.ensure_schema(driver, imported)
                    return self.delete_box_rows_in_batches(driver, imported, clean_boxes)
                finally:
                    self.close_driver(driver)
            return self.with_typedb_retries(operation)
        except Exception as error:  # noqa: BLE001 - preserve the original write failure while reporting cleanup state.
            return {"status": "error", "boxes": clean_boxes, "reason": str(error)[:180]}

    def graph_for_boxes(
        self,
        graph: PortfolioOntology,
        boxes: Iterable[str],
        retain_cross_box_relations: bool = False,
    ) -> PortfolioOntology:
        """Return a persistence-safe graph slice for the requested ontology boxes.

        Static boxes are normally independent, except for a small number of
        declaration edges such as ``TBox RuleBox -> RuleBox RuleRegistry``.
        A targeted RuleBox refresh must retain those edges without re-inserting
        the already durable TBox endpoint.  External endpoints are therefore
        kept only as in-memory lookup rows and are excluded from node writes.
        """
        allowed = {str(item or "").strip() for item in boxes or [] if str(item or "").strip()}
        if not allowed:
            return PortfolioOntology(str(graph.portfolio_id or "typedb-empty"))
        clone = copy.deepcopy(graph)
        source_entities = list(clone.entities)
        source_entity_ids = {str(item.entity_id or "") for item in source_entities if str(item.entity_id or "")}
        selected_entities = [
            item
            for item in source_entities
            if str((item.properties or {}).get("ontologyBox") or "ABox") in allowed
        ]
        selected_entity_ids = {str(item.entity_id or "") for item in selected_entities}
        selected_relations = [
            item
            for item in clone.relations
            if str((item.properties or {}).get("ontologyBox") or "ABox") in allowed
            and str(item.source or "") in source_entity_ids
            and str(item.target or "") in source_entity_ids
            and (
                retain_cross_box_relations
                or (
                    str(item.source or "") in selected_entity_ids
                    and str(item.target or "") in selected_entity_ids
                )
            )
        ]
        if retain_cross_box_relations:
            endpoint_ids = {
                str(endpoint or "")
                for relation in selected_relations
                for endpoint in [relation.source, relation.target]
                if str(endpoint or "")
            }
            external_endpoint_ids = endpoint_ids - selected_entity_ids
            selected_entities.extend(
                item
                for item in source_entities
                if str(item.entity_id or "") in external_endpoint_ids
            )
            for item in selected_entities:
                if str(item.entity_id or "") in external_endpoint_ids:
                    item.properties = dict(item.properties or {})
                    item.properties["_typedbExternalEndpointRef"] = True
        clone.entities = selected_entities
        clone.relations = selected_relations
        clone.evidence = [
            item
            for item in clone.evidence
            if str((item.value or {}).get("ontologyBox") or "ABox") in allowed
        ]
        return clone

    def graph_with_static_seed_generation(
        self,
        graph: PortfolioOntology,
        boxes: Iterable[str],
        generation_id,
    ) -> PortfolioOntology:
        """Attach immutable static generation IDs to selected persisted boxes.

        ``generation_id`` accepts either one shared value or a per-box map.
        The latter is required for targeted static updates: a changed RuleBox
        must still link to the active TBox generation without rewriting that
        TBox.  Cross-box endpoint references receive their owning box's
        storage identity but remain excluded from node writes.
        """
        selected_boxes = {str(item or "").strip() for item in boxes or [] if str(item or "").strip()}
        if isinstance(generation_id, dict):
            generation_by_box = {
                str(box or "").strip(): str(value or "").strip()
                for box, value in generation_id.items()
                if str(box or "").strip() and str(value or "").strip()
            }
        else:
            clean_generation = str(generation_id or "").strip()
            generation_by_box = {
                box: clean_generation
                for box in selected_boxes
                if clean_generation
            }
        if not generation_by_box or not selected_boxes:
            return graph
        clone = copy.deepcopy(graph)
        for item in clone.entities:
            properties = dict(item.properties or {})
            box = str(properties.get("ontologyBox") or "ABox")
            generation = generation_by_box.get(box)
            if generation:
                properties["snapshotId"] = generation
                properties["staticSeedGeneration"] = generation
                item.properties = properties
        for item in clone.relations:
            properties = dict(item.properties or {})
            box = str(properties.get("ontologyBox") or "ABox")
            generation = generation_by_box.get(box)
            if generation:
                properties["snapshotId"] = generation
                properties["staticSeedGeneration"] = generation
                item.properties = properties
        return clone

    def abox_candidate_graph(self, graph: PortfolioOntology) -> PortfolioOntology:
        """Return one immutable ABox generation ready for pointer activation.

        ABox records stay in their normal box. Their storage identity already
        includes ``snapshotId``, so a verified candidate can coexist with the
        currently active generation without rewriting thousands of records.
        """
        return self.graph_for_boxes(graph, ["ABox"])

    @staticmethod
    def abox_snapshot_id_from_graph(graph: PortfolioOntology) -> str:
        worldview = dict(getattr(graph, "worldview", {}) or {})
        snapshot_id = str(worldview.get("aboxSnapshotId") or worldview.get("snapshotId") or "").strip()
        if snapshot_id:
            return snapshot_id
        for item in list(getattr(graph, "entities", []) or []):
            properties = dict(getattr(item, "properties", {}) or {})
            snapshot_id = str(properties.get("aboxSnapshotId") or properties.get("snapshotId") or "").strip()
            if snapshot_id:
                return snapshot_id
        return ""

    def abox_active_pointer_graph(
        self,
        graph: PortfolioOntology,
        previous_snapshot_id: str = "",
        pending_activation: bool = True,
    ) -> PortfolioOntology:
        worldview = dict(getattr(graph, "worldview", {}) or {})
        snapshot_id = self.abox_snapshot_id_from_graph(graph)
        fingerprint = str(worldview.get("materialFingerprint") or "").strip()
        if not snapshot_id:
            return PortfolioOntology(str(graph.portfolio_id or "typedb-abox-control"))
        as_of = str(worldview.get("asOf") or worldview.get("generatedAt") or utc_now())
        target_symbols = clean_symbols_from_payload(
            worldview.get("inferenceTargetSymbols") or worldview.get("targetSymbols") or []
        )
        world_id = str(worldview.get("worldId") or "").strip()
        world_context = {
            "worldId": world_id,
            "worldType": str(worldview.get("worldType") or ""),
            "tenantId": str(worldview.get("tenantId") or ""),
            "accountId": str(worldview.get("accountId") or graph.portfolio_id or ""),
        }
        world_suffix = (":world:" + hashlib.sha256(world_id.encode("utf-8")).hexdigest()[:16]) if world_id else ""
        pointer = OntologyEntity(
            entity_id="abox-active-pointer" + world_suffix,
            label="Active ABox generation",
            kind="abox-active-pointer",
            properties={
                "ontologyBox": "ABoxControl",
                **world_context,
                "tboxClass": "ABoxActivePointer",
                "snapshotId": snapshot_id,
                "aboxSnapshotId": snapshot_id,
                "materialFingerprint": fingerprint,
                "projectionRunId": str(worldview.get("projectionRunId") or ""),
                "asOf": as_of,
            },
        )
        entities = [pointer]
        # Store the activation hand-off in the same atomic ABoxControl write as
        # the pointer. This is cleared only after a native InferenceBox is
        # aligned, or after an explicit rollback to the retained predecessor.
        if pending_activation and str(previous_snapshot_id or "").strip() != snapshot_id:
            entities.append(OntologyEntity(
                entity_id="abox-activation-pending" + world_suffix,
                label="ABox activation pending native inference",
                kind="abox-activation-pending",
                properties={
                    "ontologyBox": "ABoxControl",
                    **world_context,
                    "tboxClass": "ABoxActivationPending",
                    "snapshotId": snapshot_id,
                    "aboxSnapshotId": snapshot_id,
                    "candidateAboxSnapshotId": snapshot_id,
                    "previousAboxSnapshotId": str(previous_snapshot_id or "").strip(),
                    "materialFingerprint": fingerprint,
                    "projectionRunId": str(worldview.get("projectionRunId") or ""),
                    "asOf": as_of,
                    "targetSymbols": target_symbols,
                    "activationStatus": "pending-native-inference",
                },
            ))
        return PortfolioOntology(str(graph.portfolio_id or "typedb-abox-control"), entities=entities)

    def activate_abox_generation(self, snapshot_id: str, world_id: str = "") -> Dict[str, object]:
        """Point the active ABox control record at a verified generation.

        This is used to restore the last aligned ABox when a newly activated
        generation cannot complete TypeDB native inference. It only accepts a
        generation with a complete ABox marker, so it cannot promote a partial
        write left behind by an interrupted worker.
        """
        clean_snapshot_id = str(snapshot_id or "").strip()
        if not clean_snapshot_id:
            return {
                "configured": bool(self.address),
                "status": "skipped",
                "graphStore": "typedb",
                "reason": "ABox snapshot id is empty.",
            }
        if self.scoped_manifest_metadata(clean_snapshot_id, world_id):
            return typedb_call_for_world(
                self.activate_scoped_abox_manifest,
                clean_snapshot_id,
                world_id=world_id,
            )
        marker = next((
            item
            for item in self.abox_projection_marker_rows(world_id)
            if str(item.get("aboxSnapshotId") or item.get("snapshotId") or "").strip() == clean_snapshot_id
        ), None)
        metadata = self.abox_metadata_from_marker(marker or {}) if marker else {}
        if str(metadata.get("status") or "") != "ok":
            return {
                "configured": bool(self.address),
                "status": "error",
                "graphStore": "typedb",
                "aboxSnapshotId": clean_snapshot_id,
                "reason": str(metadata.get("reason") or "ABox generation is not complete."),
            }
        imported = self.driver_imports()
        if imported[0] is None:
            return self.driver_missing_result(imported[1], PortfolioOntology("typedb-abox-control"))
        pointer_graph = self.abox_active_pointer_graph(PortfolioOntology(
            "typedb-abox-control",
            worldview={
                "aboxSnapshotId": clean_snapshot_id,
                "materialFingerprint": str(metadata.get("materialFingerprint") or ""),
                "projectionRunId": str(metadata.get("projectionRunId") or ""),
                "asOf": str(metadata.get("asOf") or utc_now()),
                "worldId": str(world_id or metadata.get("worldId") or ""),
            },
        ), pending_activation=False)
        try:
            def operation():
                driver = self.open_driver(imported)
                try:
                    self.ensure_database(driver)
                    self.delete_world_abox_control_rows(driver, imported, world_id)
                    self.write_graph(driver, imported, pointer_graph, delete_boxes=[])
                finally:
                    self.close_driver(driver)

            self.with_typedb_retries(operation)
            active = self.active_abox_metadata(world_id)
            if str(active.get("status") or "") != "ok" or str(active.get("aboxSnapshotId") or "") != clean_snapshot_id:
                return {
                    "configured": True,
                    "status": "error",
                    "graphStore": "typedb",
                    "aboxSnapshotId": clean_snapshot_id,
                    "reason": "ABox control pointer verification failed after activation.",
                    "activeAbox": active,
                }
            return {
                "configured": True,
                "status": "ok",
                "graphStore": "typedb",
                "aboxSnapshotId": clean_snapshot_id,
                "activeAbox": active,
            }
        except Exception as error:  # noqa: BLE001 - caller preserves the diagnostic failure state.
            return {
                "configured": True,
                "status": "error",
                "graphStore": "typedb",
                "aboxSnapshotId": clean_snapshot_id,
                "reasonCode": typedb_error_code(error),
                "reason": str(error)[:220],
            }

    def finalize_abox_generation(self, active_snapshot_id: str, previous_snapshot_id: str = "", world_id: str = "") -> Dict[str, object]:
        """Complete an ABox activation after aligned native inference.

        Clearing the durable activation journal is a correctness boundary;
        deleting the prior generation is storage maintenance. Keeping those
        operations separate prevents one expensive TypeDB delete from making a
        valid realtime inference appear incomplete or retriggering alerts.
        """
        active_id = str(active_snapshot_id or "").strip()
        previous_id = str(previous_snapshot_id or "").strip()
        active_metadata = self.active_abox_metadata(world_id)
        if str(active_metadata.get("scopedAboxManifestVersion") or "") == SCOPED_ABOX_MANIFEST_VERSION:
            return self.finalize_scoped_abox_manifest(active_id, previous_id, world_id)
        if not active_id:
            return {
                "configured": bool(self.address),
                "status": "error",
                "graphStore": "typedb",
                "activeAboxSnapshotId": active_id,
                "previousAboxSnapshotId": previous_id,
                "reason": "Active ABox snapshot id is empty.",
            }
        active = self.active_abox_metadata(world_id)
        if str(active.get("status") or "") != "ok" or str(active.get("aboxSnapshotId") or "") != active_id:
            return {
                "configured": bool(self.address),
                "status": "error",
                "graphStore": "typedb",
                "activeAboxSnapshotId": active_id,
                "previousAboxSnapshotId": previous_id,
                "reason": "Active ABox changed before retained-generation cleanup.",
            }
        control = typedb_call_for_world(
            self.activate_abox_generation,
            active_id,
            world_id=world_id,
        )
        cleared = str(control.get("status") or "") == "ok"
        cleanup_deferred = bool(previous_id and previous_id != active_id)
        return {
            "configured": True,
            "status": "ok" if cleared else "error",
            "graphStore": "typedb",
            "activeAboxSnapshotId": active_id,
            "previousAboxSnapshotId": previous_id,
            "clearedPendingActivation": cleared,
            "cleanupDeferred": cleanup_deferred,
            "cleanup": {
                "status": "deferred" if cleanup_deferred else "not-required",
                "previousAboxSnapshotId": previous_id,
                "reason": (
                    "Inactive ABox cleanup will run in bounded maintenance slices."
                    if cleanup_deferred
                    else "No prior ABox generation requires cleanup."
                ),
            },
            "control": control,
            "reason": "" if cleared else str(control.get("reason") or "ABox activation journal clear failed."),
        }

    def inferencebox_matches_pending_abox_activation(
        self,
        inferencebox: Dict[str, object],
        candidate_snapshot_id: str,
        target_symbols: Iterable[str] = None,
    ) -> bool:
        status = str((inferencebox or {}).get("status") or "").strip().lower()
        native_used = bool((inferencebox or {}).get("nativeTypeDbReasoningUsed"))
        native_completed = bool(
            (inferencebox or {}).get("nativeTypeDbReasoningCompleted")
            or (inferencebox or {}).get("typedbNativeRuleEvaluationCompleted")
        )
        if status == "ok" and not native_used:
            return False
        if status == "empty" and not native_completed:
            return False
        if status not in {"ok", "empty"}:
            return False
        if not bool((inferencebox or {}).get("generationAligned")):
            return False
        if str((inferencebox or {}).get("sourceAboxSnapshotId") or "").strip() != str(candidate_snapshot_id or "").strip():
            return False
        expected = set(clean_symbols_from_payload(target_symbols or []))
        actual = set(clean_symbols_from_payload((inferencebox or {}).get("targetSymbols") or []))
        return not expected or expected.issubset(actual)

    @coordinated_typedb_projection_write(
        "pending-abox-recovery",
        typedb_projection_world_from_recovery,
    )
    def recover_pending_abox_activation(
        self,
        world_id: str = "",
        max_staged_target_symbols: int = 0,
    ) -> Dict[str, object]:
        """Finish or roll back an interrupted ABox-to-InferenceBox hand-off."""
        try:
            pending = self.pending_abox_activation(world_id)
        except Exception as error:  # noqa: BLE001 - caller must block a new activation when control state is unreadable.
            return {
                "configured": bool(self.address),
                "status": "error",
                "graphStore": "typedb",
                "reasonCode": typedb_error_code(error),
                "reason": "ABox activation journal lookup failed: " + str(error)[:180],
            }
        if str(pending.get("status") or "") == "empty":
            return {
                "configured": True,
                "status": "skipped",
                "graphStore": "typedb",
                "reason": "No pending ABox activation exists.",
            }
        if str(pending.get("status") or "") != "pending":
            return {
                "configured": True,
                "status": "error",
                "graphStore": "typedb",
                "pendingActivation": pending,
                "reason": "ABox activation journal is invalid.",
            }
        candidate_id = str(pending.get("candidateAboxSnapshotId") or "").strip()
        previous_id = str(pending.get("previousAboxSnapshotId") or "").strip()
        target_symbols = clean_symbols_from_payload(pending.get("targetSymbols") or [])
        try:
            staged_target_cap = max(0, min(200, int(float(max_staged_target_symbols or 0))))
        except (TypeError, ValueError):
            staged_target_cap = 0
        active = self.active_abox_metadata(world_id)
        active_id = str(active.get("aboxSnapshotId") or "").strip()
        activation_status = str(pending.get("activationStatus") or "pending-native-inference")
        if str(active.get("status") or "") != "ok":
            if activation_status == "staged-native-inference" and not previous_id:
                return {
                    "configured": True,
                    "status": "staged",
                    "graphStore": "typedb",
                    "candidateAboxSnapshotId": candidate_id,
                    "previousAboxSnapshotId": previous_id,
                    "activeAboxSnapshotId": active_id,
                    "pendingActivation": pending,
                    "reason": "Initial ABox candidate is staged and awaits its first native inference activation.",
                }
            return {
                "configured": True,
                "status": "error",
                "graphStore": "typedb",
                "pendingActivation": pending,
                "activeAbox": active,
                "reason": "Pending ABox activation has no complete active generation.",
            }
        if active_id != candidate_id:
            if activation_status == "staged-native-inference":
                if (
                    world_type_from_id(world_id) == SHARED_PREMISE_WORLD_TYPE
                    and previous_id
                    and active_id == previous_id
                ):
                    # SharedPremiseWorld is rebuilt from the current bounded
                    # source request before its RuleBox runs. A candidate that
                    # never replaced the verified predecessor therefore has no
                    # observable generation to resume. Clear only its journal
                    # so the current request can stage a fresh targeted view.
                    control = typedb_call_for_world(
                        self.activate_abox_generation,
                        active_id,
                        world_id=world_id,
                    )
                    cleared = str(control.get("status") or "") == "ok"
                    return {
                        "configured": True,
                        "status": "discarded-staged-shared-premise" if cleared else "error",
                        "graphStore": "typedb",
                        "candidateAboxSnapshotId": candidate_id,
                        "previousAboxSnapshotId": previous_id,
                        "activeAboxSnapshotId": active_id,
                        "targetSymbols": target_symbols,
                        "control": control,
                        "recoveryMode": "discard-inactive-shared-premise-candidate",
                        "reason": (
                            "An inactive SharedPremiseWorld candidate was discarded so the current bounded request can stage a fresh generation."
                            if cleared
                            else str(control.get("reason") or "SharedPremiseWorld control restoration failed.")
                        ),
                    }
                if (
                    staged_target_cap
                    and len(target_symbols) > staged_target_cap
                    and previous_id
                    and active_id == previous_id
                ):
                    # The candidate never became active.  Retain the verified
                    # predecessor and clear only this journal while the
                    # projection coordinator is held, so a later scheduler
                    # cannot resume an interrupted wider batch.
                    control = typedb_call_for_world(
                        self.activate_abox_generation,
                        active_id,
                        world_id=world_id,
                    )
                    return {
                        "configured": True,
                        "status": "discarded-staged-batch" if str(control.get("status") or "") == "ok" else "error",
                        "graphStore": "typedb",
                        "candidateAboxSnapshotId": candidate_id,
                        "previousAboxSnapshotId": previous_id,
                        "activeAboxSnapshotId": active_id,
                        "targetSymbols": target_symbols,
                        "maxStagedTargetSymbols": staged_target_cap,
                        "control": control,
                        "reason": (
                            "An interrupted staged ABox batch exceeded the current scheduler target cap and was discarded before native inference."
                            if str(control.get("status") or "") == "ok"
                            else str(control.get("reason") or "ABox control restoration failed.")
                        ),
                    }
                return {
                    "configured": True,
                    "status": "staged",
                    "graphStore": "typedb",
                    "candidateAboxSnapshotId": candidate_id,
                    "previousAboxSnapshotId": previous_id,
                    "activeAboxSnapshotId": active_id,
                    "pendingActivation": pending,
                    "reason": "A complete ABox candidate is staged and awaits native inference activation.",
                }
            # The pointer already moved by a successful rollback or a later
            # repair. Rewriting that verified pointer clears a stale journal.
            control = typedb_call_for_world(
                self.activate_abox_generation,
                active_id,
                world_id=world_id,
            )
            return {
                "configured": True,
                "status": "cleared-stale" if str(control.get("status") or "") == "ok" else "error",
                "graphStore": "typedb",
                "candidateAboxSnapshotId": candidate_id,
                "activeAboxSnapshotId": active_id,
                "previousAboxSnapshotId": previous_id,
                "control": control,
                "reason": "" if str(control.get("status") or "") == "ok" else str(control.get("reason") or "ABox control clear failed."),
            }
        if not target_symbols and not previous_id:
            # A journal with no target subject cannot ever prove that a
            # native InferenceBox covered a requested investment decision.
            # Keeping it pending instead blocks every successor Manifest and
            # used to tempt recovery into an unbounded historical read. The
            # candidate is already the verified active Manifest, so replacing
            # its control pointer without a pending journal is safe: no ABox
            # fact, scope generation, or prior decision is removed.
            finalization = typedb_call_for_world(
                self.finalize_abox_generation,
                candidate_id,
                previous_id,
                world_id=world_id,
            )
            finalized = str(finalization.get("status") or "") == "ok"
            return {
                "configured": True,
                "status": "finalized-empty-target" if finalized else "error",
                "graphStore": "typedb",
                "candidateAboxSnapshotId": candidate_id,
                "previousAboxSnapshotId": previous_id,
                "pendingActivation": pending,
                "finalization": finalization,
                "reason": (
                    "Cleared an active ABox activation journal with no requested target symbols; the next bounded cycle may stage a successor Manifest."
                    if finalized
                    else str(finalization.get("reason") or "ABox activation journal clear failed.")
                ),
            }
        if not target_symbols:
            return {
                "configured": True,
                "status": "invalid-empty-target",
                "graphStore": "typedb",
                "candidateAboxSnapshotId": candidate_id,
                "previousAboxSnapshotId": previous_id,
                "pendingActivation": pending,
                "reason": (
                    "Pending ABox activation lost its target symbols after a predecessor existed. "
                    "Recovery is blocked to avoid an unbounded InferenceBox read or an unsafe rollback."
                ),
            }
        if (
            staged_target_cap
            and len(target_symbols) > staged_target_cap
            and previous_id
            and active_id == candidate_id
        ):
            # A hard-isolation timeout records a smaller next scheduler cap.
            # The candidate may already be the active ABox pointer even
            # though its native InferenceBox never verified.  Retrying its
            # original wide target set here would defeat that protection and
            # can hold every newer mailbox revision behind the same timeout.
            #
            # The pending journal proves that this candidate has no aligned
            # inference result yet, while ``previous_id`` is the last
            # verified generation retained specifically for recovery.  A
            # control-only rollback is therefore safe: it preserves the
            # verified judgement and lets the current bounded scheduler
            # stage fresh facts instead of resuming an obsolete wide batch.
            rollback = typedb_call_for_world(
                self.activate_abox_generation,
                previous_id,
                world_id=world_id,
            )
            restored = str(rollback.get("status") or "") == "ok"
            return {
                "configured": True,
                "status": "restored" if restored else "error",
                "graphStore": "typedb",
                "candidateAboxSnapshotId": candidate_id,
                "previousAboxSnapshotId": previous_id,
                "activeAboxSnapshotId": active_id,
                "targetSymbols": target_symbols,
                "maxStagedTargetSymbols": staged_target_cap,
                "pendingActivation": pending,
                "rollback": rollback,
                "recoveryMode": "rollback-oversized-active-candidate",
                "reason": (
                    "An interrupted active ABox batch exceeded the current scheduler target cap and was rolled back before retrying native inference."
                    if restored
                    else str(rollback.get("reason") or "ABox control rollback failed.")
                ),
            }
        try:
            recovery_metadata = typedb_call_for_world(
                self.inferencebox_recovery_metadata,
                world_id=world_id,
            )
        except Exception as error:  # noqa: BLE001 - retain the candidate journal when the marker cannot be read.
            recovery_metadata = {
                "configured": True,
                "status": "error",
                "graphStore": "typedb",
                "reason": "InferenceBox recovery marker lookup failed: " + str(error)[:180],
            }
        recovery_metadata = dict(recovery_metadata or {}) if isinstance(recovery_metadata, dict) else {}
        recovery_outcome = str(recovery_metadata.get("nativeInferenceOutcome") or "").strip().lower()
        recovery_completed = bool(recovery_metadata.get("nativeTypeDbReasoningCompleted"))
        recovery_source_id = str(recovery_metadata.get("sourceAboxSnapshotId") or "").strip()
        recovery_targets = clean_symbols_from_payload(recovery_metadata.get("targetSymbols") or [])
        recovery_marker_ready = (
            str(recovery_metadata.get("status") or "") == "ok"
            and recovery_completed
            and recovery_outcome in {"matched", "no-match"}
        )
        # A recovery must not expand every entity, relation, and trace from a
        # historical InferenceBox.  The active generation marker is the same
        # provenance proof used by the realtime commit path: it contains the
        # source ABox, native-completion state, outcome, and target coverage.
        # Detailed rows remain an asynchronous audit concern.
        inferencebox = {
            "configured": True,
            "graphStore": "typedb",
            "status": (
                "ok" if recovery_marker_ready and recovery_outcome == "matched"
                else "empty" if recovery_marker_ready and recovery_outcome == "no-match"
                else "stale-generation"
            ),
            "nativeTypeDbReasoningUsed": bool(
                recovery_marker_ready and recovery_outcome == "matched"
            ),
            "nativeTypeDbReasoningCompleted": recovery_completed,
            "typedbNativeRuleEvaluationCompleted": recovery_completed,
            "nativeInferenceOutcome": recovery_outcome,
            "generationAligned": bool(
                recovery_marker_ready
                and recovery_source_id == candidate_id
                and set(target_symbols).issubset(set(recovery_targets))
            ),
            "sourceAboxSnapshotId": recovery_source_id,
            "targetSymbols": recovery_targets,
            "inferenceGenerationId": str(recovery_metadata.get("inferenceGenerationId") or "").strip(),
            "querySource": str(
                recovery_metadata.get("querySource")
                or "typedb-active-inference-generation-marker"
            ),
            "durableReadback": False,
            "recoveryMetadata": recovery_metadata,
        }
        if str(recovery_metadata.get("status") or "") == "error" and active_id != candidate_id:
            return {
                "configured": True,
                "status": "error",
                "graphStore": "typedb",
                "candidateAboxSnapshotId": candidate_id,
                "previousAboxSnapshotId": previous_id,
                "reason": str(recovery_metadata.get("reason") or "InferenceBox recovery marker is unreadable.")[:220],
            }
        if self.inferencebox_matches_pending_abox_activation(
            inferencebox,
            candidate_id,
            target_symbols,
        ):
            finalization = typedb_call_for_world(
                self.finalize_abox_generation,
                candidate_id,
                previous_id,
                world_id=world_id,
            )
            return {
                "configured": True,
                "status": "finalized" if str(finalization.get("status") or "") == "ok" else "error",
                "graphStore": "typedb",
                "candidateAboxSnapshotId": candidate_id,
                "previousAboxSnapshotId": previous_id,
                "inferenceBox": inferencebox,
                "finalization": finalization,
                "reason": "" if str(finalization.get("status") or "") == "ok" else str(finalization.get("reason") or "ABox finalization failed."),
            }
        if (
            active_id == candidate_id
            and previous_id
            and world_type_from_id(world_id) == SHARED_PREMISE_WORLD_TYPE
        ):
            # SharedPremiseWorld is rebuilt from the current bounded source
            # request. After a process interruption, retaining an active
            # candidate with no aligned InferenceBox only makes every newer
            # request read a stale generation. Restore the last proven pair;
            # the current request will stage fresh premises and run them under
            # the atomic staged-ABox execution boundary.
            rollback = typedb_call_for_world(
                self.activate_abox_generation,
                previous_id,
                world_id=world_id,
            )
            restored = str(rollback.get("status") or "") == "ok"
            return {
                "configured": True,
                "status": "restored" if restored else "error",
                "graphStore": "typedb",
                "candidateAboxSnapshotId": candidate_id,
                "previousAboxSnapshotId": previous_id,
                "activeAboxSnapshotId": active_id,
                "targetSymbols": target_symbols,
                "pendingActivation": pending,
                "inferenceBox": inferencebox,
                "rollback": rollback,
                "recoveryMode": "rollback-interrupted-shared-premise-candidate",
                "reason": (
                    "Interrupted SharedPremiseWorld candidate was restored to the last aligned generation."
                    if restored
                    else str(rollback.get("reason") or "SharedPremiseWorld rollback failed.")
                ),
            }
        if active_id == candidate_id:
            # The durable pointer already proves this candidate is a complete
            # ABox generation.  A missing or stale InferenceBox must not make
            # us scan and restore an older Manifest: that turns an interrupted
            # one-target cycle into a historical ABox read and can repeatedly
            # exceed the isolated worker timeout.  Keep the activation journal
            # in place (so no judgement can use this ABox yet) and resume the
            # exact bounded native inference on the active candidate.
            return {
                "configured": True,
                "status": "retry-required",
                "graphStore": "typedb",
                "candidateAboxSnapshotId": candidate_id,
                "previousAboxSnapshotId": previous_id,
                "activeAboxSnapshotId": active_id,
                "targetSymbols": target_symbols,
                "pendingActivation": pending,
                "inferenceBox": inferencebox,
                "recoveryMode": "resume-active-candidate",
                "reason": "The complete active ABox candidate is awaiting a retry of bounded TypeDB native inference.",
            }
        if not previous_id:
            # There is no prior verified generation to restore. The candidate
            # remains staged and cannot produce investment judgement until a
            # later same-material cycle retries native inference.
            return {
                "configured": True,
                "status": "retry-required",
                "graphStore": "typedb",
                "candidateAboxSnapshotId": candidate_id,
                "previousAboxSnapshotId": previous_id,
                "targetSymbols": target_symbols,
                "pendingActivation": pending,
                "inferenceBox": inferencebox,
                "reason": "Initial ABox activation is awaiting a retry of TypeDB native inference.",
            }
        rollback = typedb_call_for_world(
            self.activate_abox_generation,
            previous_id,
            world_id=world_id,
        )
        return {
            "configured": True,
            "status": "restored" if str(rollback.get("status") or "") == "ok" else "error",
            "graphStore": "typedb",
            "candidateAboxSnapshotId": candidate_id,
            "previousAboxSnapshotId": previous_id,
            "inferenceBox": inferencebox,
            "rollback": rollback,
            "reason": "" if str(rollback.get("status") or "") == "ok" else str(rollback.get("reason") or "ABox rollback failed."),
        }

    def write_graph(
        self,
        driver,
        imported,
        graph: PortfolioOntology,
        delete_boxes: Iterable[str] = None,
    ) -> None:
        _TypeDB, _Credentials, _DriverOptions, _DriverTlsConfig, TransactionType = imported[0]
        boxes = node_boxes(graph) if delete_boxes is None else list(delete_boxes or [])
        static_replacement_boxes = {"TBox", "RuleBox", "RuleBoxGovernance", "LanguageGovernance"}
        static_boxes = sorted(static_replacement_boxes.intersection(boxes))
        # A broad static delete scans the whole ontology-node/assertion space
        # on a large durable ABox.  Delete each static box in bounded TypeQL
        # batches before inserting its replacement instead.  This keeps a
        # RuleBox-only policy change from monopolising the TypeDB writer.
        if static_boxes:
            self.delete_box_rows_in_batches(driver, imported, static_boxes)
        delete_queries = self.delete_queries(
            box for box in boxes
            if box not in static_replacement_boxes
        )
        graph_boxes = node_boxes(graph)
        static_graph_write = bool(static_replacement_boxes.intersection(graph_boxes))
        insert_queries = (
            self.static_graph_insert_queries(graph)
            if static_graph_write
            else self.graph_insert_queries(graph)
        )
        if not delete_queries and not insert_queries:
            return
        transaction_query_count = (
            self.abox_write_transaction_query_count()
            if "ABox" in graph_boxes
            else (
                self.static_write_transaction_query_count()
                if static_graph_write
                else self.graph_write_transaction_query_count()
            )
        )
        # Large static replacements span multiple batches. Commit their deletes
        # first so a later insert batch cannot collide with an old @unique
        # storage ID. Small ABoxControl pointer swaps remain one transaction.
        phases = [delete_queries, insert_queries] if static_boxes else [delete_queries + insert_queries]
        for queries in phases:
            for offset in range(0, len(queries), transaction_query_count):
                query_batch = queries[offset: offset + transaction_query_count]

                def write_batch():
                    with typedb_operation_timeout(self.write_operation_timeout_seconds(), "TypeDB graph write batch"):
                        with driver.transaction(
                            self.database,
                            TransactionType.WRITE,
                            options=self.write_transaction_options(),
                        ) as tx:
                            for query in query_batch:
                                tx.query(query).resolve()
                            tx.commit()

                self.with_typedb_retries(write_batch)

    def clear_inferencebox(self, world_id: str = "") -> Dict[str, object]:
        if not self.address:
            return {
                "configured": False,
                "status": "disabled",
                "graphStore": "typedb",
                "reason": "TypeDB ontology storage is not configured.",
            }
        imported = self.driver_imports()
        if imported[0] is None:
            return {
                "configured": True,
                "status": "driver-missing",
                "graphStore": "typedb",
                "reason": "typedb-driver Python package is not installed: " + str(imported[1])[:160],
            }
        _TypeDB, _Credentials, _DriverOptions, _DriverTlsConfig, TransactionType = imported[0]
        try:
            def operation():
                driver = self.open_driver(imported)
                try:
                    self.ensure_database(driver)
                    self.ensure_schema(driver, imported)
                    with driver.transaction(self.database, TransactionType.WRITE) as tx:
                        world_clause = (
                            ", has ontology-world-id " + typedb_string(world_id)
                            if str(world_id or "").strip()
                            else ""
                        )
                        delete_queries = (
                            [
                                'match $r isa ontology-assertion, has ontology-box "InferenceBox"'
                                + world_clause + "; delete $r;",
                                'match $n isa ontology-node, has ontology-box "InferenceBox"'
                                + world_clause + "; delete $n;",
                            ]
                            if world_clause
                            else self.delete_queries(["InferenceBox"])
                        )
                        for query in delete_queries:
                            tx.query(query).resolve()
                        tx.commit()
                finally:
                    self.close_driver(driver)
            self.with_typedb_retries(operation)
            return {
                "configured": True,
                "status": "ok",
                "graphStore": "typedb",
                "worldId": str(world_id or ""),
                "clearedBox": "InferenceBox",
            }
        except Exception as error:  # noqa: BLE001 - caller reports clear failure as inference boundary status.
            return {
                "configured": True,
                "status": "error",
                "graphStore": "typedb",
                "reasonCode": typedb_error_code(error),
                "reason": str(error)[:220],
            }

